class SettingsScreen extends StatelessWidget { const SettingsScreen({super.key}); @override Widget build(BuildContext context)=>CustomScrollView(slivers:[const SliverAppBar.large(title:Text('Settings')),SliverPadding(padding:const EdgeInsets.all(16),sliver:SliverList(delegate:SliverChildListDelegate([_card(context,Icons.memory,'Runtime','Pinned Dart and Flutter runtime information will be shown here.'),_card(context,Icons.offline_bolt,'Offline mode','Core lessons, projects and source editing are designed to work offline.'),_card(context,Icons.bug_report,'Debugging','Stack traces, breakpoints and variables belong to the runtime/debug bridge.')])))]); Widget _card(BuildContext c,IconData i,String t,String b)=>Card(margin:const EdgeInsets.only(bottom:10),child:ListTile(contentPadding:const EdgeInsets.all(16),leading:Icon(i),title:Text(t),subtitle:Padding(padding:const EdgeInsets.only(top:6),child:Text(b)))); }
